package com.gearmeup;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * A boss from bosses.json: its weaknesses and one or more gear setups.
 */
public final class Boss
{
	private final String name;
	private final String category;
	private final List<String> attributes;
	private final List<String> immuneTo;
	private final String elementalWeakness;
	private final int elementalWeaknessPercent;
	private final Map<String, Integer> defence;
	private final int slayerLevel;
	private final boolean slayerOnly;
	private final String info;
	private final List<String> searchTerms = new ArrayList<>();
	private final List<GearSetup> setups;

	Boss(String name, String category, List<String> attributes, List<String> immuneTo, String elementalWeakness,
		int elementalWeaknessPercent, Map<String, Integer> defence, int slayerLevel, boolean slayerOnly, String info,
		List<String> aliases, List<GearSetup> setups)
	{
		this.name = name;
		this.category = category;
		this.attributes = Collections.unmodifiableList(attributes);
		this.immuneTo = Collections.unmodifiableList(immuneTo);
		this.elementalWeakness = elementalWeakness == null || elementalWeakness.equals("none") ? null : elementalWeakness;
		this.elementalWeaknessPercent = elementalWeaknessPercent;
		this.defence = defence == null ? Collections.emptyMap() : Collections.unmodifiableMap(defence);
		this.slayerLevel = slayerLevel;
		this.slayerOnly = slayerOnly;
		this.info = info == null ? "" : info;
		this.setups = Collections.unmodifiableList(setups);
		searchTerms.add(simplify(name));
		for (String alias : aliases)
		{
			searchTerms.add(simplify(alias));
		}
		for (GearSetup s : setups)
		{
			s.setBoss(this);
		}
	}

	public String getName()
	{
		return name;
	}

	public String getCategory()
	{
		return category;
	}

	public List<String> getAttributes()
	{
		return attributes;
	}

	public String getElementalWeakness()
	{
		return elementalWeakness;
	}

	public int getElementalWeaknessPercent()
	{
		return elementalWeaknessPercent;
	}

	public boolean isSlayerOnly()
	{
		return slayerOnly;
	}

	public List<GearSetup> getSetups()
	{
		return setups;
	}

	/** A short line about the boss: type, weaknesses, immunities, slayer requirement. */
	public String describe()
	{
		List<String> parts = new ArrayList<>();
		if (!attributes.isEmpty())
		{
			parts.add("Type: " + String.join(", ", capitalise(attributes)));
		}
		String weakest = weakestMelee();
		if (weakest != null)
		{
			parts.add("Weakest melee: " + weakest);
		}
		String weakestRanged = weakestRanged();
		if (weakestRanged != null)
		{
			parts.add("Weakest ranged: " + weakestRanged);
		}
		if (elementalWeakness != null)
		{
			parts.add("Weak to " + elementalWeakness + " spells"
				+ (elementalWeaknessPercent > 0 ? " (+" + elementalWeaknessPercent + "%)" : ""));
		}
		if (!immuneTo.isEmpty())
		{
			parts.add("Immune to " + String.join(", ", immuneTo));
		}
		if (slayerLevel > 0)
		{
			parts.add(slayerLevel + " Slayer" + (slayerOnly ? ", task only" : ""));
		}
		if (!info.isEmpty())
		{
			parts.add(info);
		}
		return String.join(". ", parts) + (parts.isEmpty() ? "" : ".");
	}

	private String weakestMelee()
	{
		return lowest("stab", "slash", "crush");
	}

	private String weakestRanged()
	{
		String key = lowest("rangedLight", "rangedStandard", "rangedHeavy");
		if (key == null)
		{
			return null;
		}
		switch (key)
		{
			case "rangedlight":
				return "light (darts, knives, thrown)";
			case "rangedstandard":
				return "standard (bows/arrows)";
			default:
				return "heavy (crossbows/bolts)";
		}
	}

	/** The key with the lowest defence among those present, or null if fewer than two are known or all equal. */
	private String lowest(String... keys)
	{
		String best = null;
		int bestValue = Integer.MAX_VALUE;
		int known = 0;
		boolean allEqual = true;
		Integer first = null;
		for (String k : keys)
		{
			Integer v = defence.get(k);
			if (v == null)
			{
				continue;
			}
			known++;
			if (first == null)
			{
				first = v;
			}
			else if (!first.equals(v))
			{
				allEqual = false;
			}
			if (v < bestValue)
			{
				bestValue = v;
				best = k.toLowerCase(Locale.ROOT);
			}
		}
		return known < 2 || allEqual ? null : best;
	}

	private static List<String> capitalise(List<String> words)
	{
		List<String> out = new ArrayList<>();
		for (String w : words)
		{
			out.add(w.isEmpty() ? w : Character.toUpperCase(w.charAt(0)) + w.substring(1));
		}
		return out;
	}

	/**
	 * True if the search text matches the name or a nickname, ignoring case, spaces and punctuation
	 * (so "kril" finds K'ril Tsutsaroth and "tob" finds Theatre of Blood).
	 */
	public boolean matches(String query)
	{
		String q = simplify(query);
		if (q.isEmpty())
		{
			return true;
		}
		for (String term : searchTerms)
		{
			if (term.contains(q))
			{
				return true;
			}
		}
		return false;
	}

	/** How well the query matches: 0 = name starts with it, 1 = name contains it, 2 = nickname only. */
	public int matchRank(String query)
	{
		String q = simplify(query);
		String n = searchTerms.get(0);
		return n.startsWith(q) ? 0 : n.contains(q) ? 1 : 2;
	}

	private static String simplify(String s)
	{
		return s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.gearmeup;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;

/**
 * Loads {@code bosses.json}: the boss list plus shared knowledge (monster-type bonuses,
 * elemental items, default weapon tiers). Field names match the JSON keys.
 */
public final class BossData
{
	private final List<Boss> bosses;
	private final Knowledge knowledge;

	private BossData(List<Boss> bosses, Knowledge knowledge)
	{
		this.bosses = Collections.unmodifiableList(bosses);
		this.knowledge = knowledge;
	}

	public List<Boss> getBosses()
	{
		return bosses;
	}

	public Knowledge getKnowledge()
	{
		return knowledge;
	}

	static BossData load(Gson gson) throws IOException
	{
		try (InputStream in = BossData.class.getResourceAsStream("bosses.json"))
		{
			if (in == null)
			{
				throw new IOException("bosses.json is missing from the plugin");
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return parse(gson.fromJson(reader, FileJson.class));
			}
		}
	}

	static BossData parse(FileJson file)
	{
		Knowledge knowledge = new Knowledge(
			nz(file.attributeItems),
			nz(file.elementItems),
			nz(file.styleWeapons),
			nz(file.slayerHelm),
			nz(file.styleGear));

		List<Boss> bosses = new ArrayList<>();
		for (BossJson b : nz(file.bosses))
		{
			List<GearSetup> setups = new ArrayList<>();
			for (SetupJson s : nz(b.setups))
			{
				Map<EquipmentInventorySlot, SlotRule> preferred = rules(s.preferred, false);
				Map<EquipmentInventorySlot, SlotRule> required = rules(s.required, true);
				if (s.weapons != null && !s.weapons.isEmpty() && !required.containsKey(EquipmentInventorySlot.WEAPON))
				{
					preferred.put(EquipmentInventorySlot.WEAPON, new SlotRule(s.weapons, false));
				}
				setups.add(new GearSetup(s.label, CombatStyle.valueOf(s.style.toUpperCase(Locale.ROOT)),
					preferred, required, s.notes == null ? "" : s.notes));
			}
			bosses.add(new Boss(b.name, b.category == null ? "Other" : b.category,
				lower(b.attributes), lower(b.immuneTo),
				b.elementalWeakness == null ? null : b.elementalWeakness.toLowerCase(Locale.ROOT),
				b.elementalWeaknessPercent, b.defence, b.slayerLevel, b.slayerOnly, b.info, nz(b.aliases), setups));
		}
		return new BossData(bosses, knowledge);
	}

	private static Map<EquipmentInventorySlot, SlotRule> rules(Map<String, List<String>> json, boolean required)
	{
		Map<EquipmentInventorySlot, SlotRule> out = new LinkedHashMap<>();
		if (json != null)
		{
			json.forEach((slot, names) ->
			{
				if (names != null && !names.isEmpty())
				{
					out.put(slot(slot), new SlotRule(names, required));
				}
			});
		}
		return out;
	}

	static EquipmentInventorySlot slot(String name)
	{
		switch (name.toLowerCase(Locale.ROOT))
		{
			case "neck":
				return EquipmentInventorySlot.AMULET;
			case "hands":
				return EquipmentInventorySlot.GLOVES;
			case "feet":
				return EquipmentInventorySlot.BOOTS;
			default:
				return EquipmentInventorySlot.valueOf(name.toUpperCase(Locale.ROOT));
		}
	}

	private static List<String> lower(List<String> in)
	{
		List<String> out = new ArrayList<>();
		for (String s : nz(in))
		{
			out.add(s.toLowerCase(Locale.ROOT));
		}
		return out;
	}

	private static <T> List<T> nz(List<T> l)
	{
		return l == null ? Collections.emptyList() : l;
	}

	private static <K, V> Map<K, V> nz(Map<K, V> m)
	{
		return m == null ? Collections.emptyMap() : m;
	}

	/**
	 * Shared item knowledge used for every boss.
	 * attributeItems: attribute -> "melee"/"ranged"/"magic"/"any" -> slot -> items (best first)
	 * elementItems: element -> slot -> items (magic setups only)
	 * styleWeapons: STAB/SLASH/CRUSH/RANGED/MAGIC -> weapons that beat their raw stats (best first)
	 * slayerHelm: "melee"/"ranged"/"magic" -> head items when on task
	 * styleGear: "melee"/"ranged"/"magic" -> slot -> general best-in-slot armour (best first)
	 */
	public static final class Knowledge
	{
		private final Map<String, Map<String, Map<String, List<String>>>> attributeItems;
		private final Map<String, Map<String, List<String>>> elementItems;
		private final Map<String, List<String>> styleWeapons;
		private final Map<String, List<String>> slayerHelm;
		private final Map<String, Map<String, List<String>>> styleGear;

		Knowledge(Map<String, Map<String, Map<String, List<String>>>> attributeItems,
			Map<String, Map<String, List<String>>> elementItems,
			Map<String, List<String>> styleWeapons,
			Map<String, List<String>> slayerHelm,
			Map<String, Map<String, List<String>>> styleGear)
		{
			this.styleGear = styleGear;
			this.attributeItems = attributeItems;
			this.elementItems = elementItems;
			this.styleWeapons = styleWeapons;
			this.slayerHelm = slayerHelm;
		}

		static Knowledge empty()
		{
			return new Knowledge(Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(),
				Collections.emptyMap());
		}

		/** Items for a monster attribute, style group ("melee"/"ranged"/"magic") and slot. "any" applies to every style. */
		List<String> attributeItems(String attribute, String styleGroup, EquipmentInventorySlot slot)
		{
			Map<String, Map<String, List<String>>> byStyle = attributeItems.get(attribute);
			if (byStyle == null)
			{
				return Collections.emptyList();
			}
			List<String> out = new ArrayList<>();
			out.addAll(slotList(byStyle.get(styleGroup), slot));
			out.addAll(slotList(byStyle.get("any"), slot));
			return out;
		}

		List<String> elementItems(String element, EquipmentInventorySlot slot)
		{
			return element == null ? Collections.emptyList() : slotList(elementItems.get(element), slot);
		}

		List<String> styleWeapons(CombatStyle style)
		{
			return styleWeapons.getOrDefault(style.name(), Collections.emptyList());
		}

		/** General best-in-slot armour for a style group ("melee"/"ranged"/"magic"), best first. */
		List<String> styleGear(String styleGroup, EquipmentInventorySlot slot)
		{
			return slotList(styleGear.get(styleGroup), slot);
		}

		List<String> slayerHelm(String styleGroup)
		{
			return slayerHelm.getOrDefault(styleGroup, Collections.emptyList());
		}

		private static List<String> slotList(Map<String, List<String>> bySlot, EquipmentInventorySlot slot)
		{
			if (bySlot == null)
			{
				return Collections.emptyList();
			}
			for (Map.Entry<String, List<String>> e : bySlot.entrySet())
			{
				if (slot(e.getKey()) == slot && e.getValue() != null)
				{
					return e.getValue();
				}
			}
			return Collections.emptyList();
		}
	}

	// ---- JSON shapes (filled by Gson) ----

	static final class FileJson
	{
		Map<String, Map<String, Map<String, List<String>>>> attributeItems;
		Map<String, Map<String, List<String>>> elementItems;
		Map<String, List<String>> styleWeapons;
		Map<String, List<String>> slayerHelm;
		Map<String, Map<String, List<String>>> styleGear;
		List<BossJson> bosses;
	}

	static final class BossJson
	{
		String name;
		String category;
		List<String> attributes;
		List<String> immuneTo;
		String elementalWeakness;
		int elementalWeaknessPercent;
		Map<String, Integer> defence;
		int slayerLevel;
		boolean slayerOnly;
		String info;
		List<String> aliases;
		List<SetupJson> setups;
	}

	static final class SetupJson
	{
		String label;
		String style;
		List<String> weapons;
		Map<String, List<String>> preferred;
		Map<String, List<String>> required;
		String notes;
	}
}

package com.gearmeup;

import net.runelite.client.game.ItemEquipmentStats;

/**
 * An equippable item the player owns, with its stats and where it was found.
 */
public final class Candidate
{
	private final int itemId;
	private final String name;
	private final ItemSource source;
	private final ItemEquipmentStats stats;

	public Candidate(int itemId, String name, ItemSource source, ItemEquipmentStats stats)
	{
		this.itemId = itemId;
		this.name = name;
		this.source = source;
		this.stats = stats;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getName()
	{
		return name;
	}

	public ItemSource getSource()
	{
		return source;
	}

	public ItemEquipmentStats getStats()
	{
		return stats;
	}

	public int getSlot()
	{
		return stats.getSlot();
	}

	/** Case- and space-insensitive "contains", so "Salve amulet (e)" matches "Salve amulet(e)". */
	public boolean nameContains(String fragment)
	{
		return normalise(name).contains(normalise(fragment));
	}

	private static String normalise(String s)
	{
		return s.toLowerCase(java.util.Locale.ROOT).replace(" ", "").replace(" ", "");
	}
}

package com.gearmeup;

/**
 * The attack style a setup is built around. Each style knows how to score a piece of gear.
 */
public enum CombatStyle
{
	STAB("Melee (stab)"),
	SLASH("Melee (slash)"),
	CRUSH("Melee (crush)"),
	RANGED("Ranged"),
	MAGIC("Magic");

	private final String displayName;

	CombatStyle(String displayName)
	{
		this.displayName = displayName;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public boolean isMelee()
	{
		return this == STAB || this == SLASH || this == CRUSH;
	}

	/** "melee", "ranged" or "magic": the key used in bosses.json. */
	public String group()
	{
		return isMelee() ? "melee" : this == RANGED ? "ranged" : "magic";
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.gearmeup;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.function.Predicate;
import java.util.function.ToDoubleFunction;
import java.util.stream.Collectors;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Picks the best owned item for every slot. Pure logic with no client access.
 *
 * <p>For each slot the first owned item from these lists wins, in order:
 * required items, slayer helmet (when on task), the boss's own preferences, items that are strong
 * against the boss's monster type (demon, dragon, undead...), elemental items (magic only), the
 * style's weapon tier list. If none are owned, items are scored by stats for the combat style.</p>
 */
public final class GearCalculator
{
	/** Slots shown in the result, in display order. */
	public static final List<EquipmentInventorySlot> SLOTS = Collections.unmodifiableList(Arrays.asList(
		EquipmentInventorySlot.HEAD,
		EquipmentInventorySlot.CAPE,
		EquipmentInventorySlot.AMULET,
		EquipmentInventorySlot.AMMO,
		EquipmentInventorySlot.WEAPON,
		EquipmentInventorySlot.BODY,
		EquipmentInventorySlot.SHIELD,
		EquipmentInventorySlot.LEGS,
		EquipmentInventorySlot.GLOVES,
		EquipmentInventorySlot.BOOTS,
		EquipmentInventorySlot.RING));

	private static final List<EquipmentInventorySlot> ARMOUR_SLOTS = Arrays.asList(
		EquipmentInventorySlot.AMULET,
		EquipmentInventorySlot.HEAD,
		EquipmentInventorySlot.CAPE,
		EquipmentInventorySlot.BODY,
		EquipmentInventorySlot.LEGS,
		EquipmentInventorySlot.GLOVES,
		EquipmentInventorySlot.BOOTS,
		EquipmentInventorySlot.RING);

	private static final String[] PROJECTILE_WORDS = {"arrow", "bolt", "javelin", "dart", "knife", "chinchompa", "thrownaxe"};
	private static final String[] NEEDS_CHARGES = {"uncharged", "(empty)", "(inactive)",
		"Craw's bow (u)", "Webweaver bow (u)", "Viggora's chainmace (u)", "Ursine chainmace (u)",
		"Thammaron's sceptre (u)", "Accursed sceptre (u)"};

	/** Not usable in normal gameplay (leagues, minigames, Gauntlet) - never suggested. */
	private static final String[] ALWAYS_EXCLUDED = {"(Last Man Standing)", "(Deadman)", "(Pete Kayer", "(basic)",
		"(attuned)", "(perfected)", "Drygore blowpipe", "Infernal tecpatl", "Nature's recurve", "Shadowflame quadrant",
		"Lithic sceptre", "Fang of the hound", "V's helm", "Searing boots", "Demonic sceptre"};

	/** Powered staves cast their own spell, so elemental tomes don't help them. */
	private static final String[] POWERED_STAVES = {"Tumeken's shadow", "Eye of ayak", "Zorya's tome", "Sanguinesti staff",
		"Trident of the", "Accursed sceptre", "Thammaron's sceptre", "Warped sceptre", "Bone staff"};

	private static final List<String> CRYSTAL_ARMOUR = Arrays.asList("Crystal helm", "Crystal body", "Crystal legs");

	/** Bows that can fire dragon arrows; crossbows that can fire dragon bolts. */
	private static final String[] DRAGON_ARROW_BOWS = {"Twisted bow", "Dark bow", "Venator bow", "Scorching bow", "3rd age bow"};
	private static final String[] DRAGON_BOLT_CROSSBOWS = {"Zaryte crossbow", "Armadyl crossbow", "Dragon crossbow", "Dragon hunter crossbow"};

	private final GearSetup setup;
	private final CombatStyle style;
	private final boolean onSlayerTask;
	private final BossData.Knowledge knowledge;
	private final Map<Integer, List<Candidate>> bySlot = new HashMap<>();
	private final Map<EquipmentInventorySlot, Candidate> picks = new EnumMap<>(EquipmentInventorySlot.class);
	private final List<String> warnings = new ArrayList<>();

	private GearCalculator(GearSetup setup, Collection<Candidate> owned, boolean onSlayerTask, List<String> ignored,
		BossData.Knowledge knowledge)
	{
		this.setup = setup;
		this.style = setup.getStyle();
		this.onSlayerTask = onSlayerTask;
		this.knowledge = knowledge == null ? BossData.Knowledge.empty() : knowledge;
		for (Candidate c : owned)
		{
			if (ignored.stream().anyMatch(c::nameContains) || containsAny(c, ALWAYS_EXCLUDED))
			{
				continue;
			}
			bySlot.computeIfAbsent(c.getSlot(), k -> new ArrayList<>()).add(c);
		}
	}

	public static GearResult calculate(GearSetup setup, Collection<Candidate> owned, boolean onSlayerTask,
		List<String> ignoredNames, BossData.Knowledge knowledge)
	{
		GearCalculator calc = new GearCalculator(setup, owned, onSlayerTask, ignoredNames, knowledge);
		calc.run();
		return new GearResult(setup, calc.picks, calc.warnings);
	}

	private void run()
	{
		pickWeaponAndShield();
		pickAmmo();
		for (EquipmentInventorySlot slot : ARMOUR_SLOTS)
		{
			pickSlot(slot, candidates(slot));
		}

		for (Candidate c : picks.values())
		{
			for (String word : NEEDS_CHARGES)
			{
				if (c.nameContains(word))
				{
					warnings.add(c.getName() + " needs charging before use.");
					break;
				}
			}
		}
	}

	// ---------------------------------------------------------------- preference lists

	/** Preference lists for a slot, most important first (not including required items). */
	private List<List<String>> preferences(EquipmentInventorySlot slot)
	{
		List<List<String>> out = new ArrayList<>();
		Candidate amulet = picks.get(EquipmentInventorySlot.AMULET);
		boolean wearingSalve = amulet != null && amulet.nameContains("Salve amulet");
		if (slot == EquipmentInventorySlot.HEAD && onSlayerTask && !wearingSalve)
		{
			// Salve and slayer helmet don't stack (salve wins), so skip the helm when wearing a salve.
			out.add(knowledge.slayerHelm(style.group()));
		}
		Candidate weapon = picks.get(EquipmentInventorySlot.WEAPON);
		if (style == CombatStyle.RANGED && weapon != null && usesCrystalArmour(weapon))
		{
			out.add(CRYSTAL_ARMOUR);
		}
		SlotRule bossRule = setup.getPreferred().get(slot);
		if (bossRule != null)
		{
			out.add(bossRule.getNames());
		}
		Boss boss = setup.getBoss();
		if (boss != null)
		{
			for (String attribute : boss.getAttributes())
			{
				out.add(knowledge.attributeItems(attribute, style.group(), slot));
			}
			if (style == CombatStyle.MAGIC && (weapon == null || !containsAny(weapon, POWERED_STAVES)))
			{
				out.add(knowledge.elementItems(boss.getElementalWeakness(), slot));
			}
		}
		if (slot == EquipmentInventorySlot.WEAPON)
		{
			out.add(knowledge.styleWeapons(style));
		}
		else
		{
			out.add(knowledge.styleGear(style.group(), slot));
		}
		return out;
	}

	private Candidate firstPreferred(List<Candidate> options, EquipmentInventorySlot slot, ToDoubleFunction<Candidate> scorer)
	{
		for (List<String> names : preferences(slot))
		{
			Candidate c = firstMatch(options, names, scorer);
			if (c != null)
			{
				return c;
			}
		}
		return null;
	}

	// ---------------------------------------------------------------- weapon + shield

	private void pickWeaponAndShield()
	{
		SlotRule requiredShield = setup.getRequired().get(EquipmentInventorySlot.SHIELD);
		// Only rule out two-handers if the player owns a required shield to wear with a one-hander.
		boolean mustUseShield = requiredShield != null
			&& firstMatch(candidates(EquipmentInventorySlot.SHIELD), requiredShield.getNames(), this::score) != null;

		List<Candidate> weapons = candidates(EquipmentInventorySlot.WEAPON).stream()
			.filter(this::suitsStyle)
			.filter(w -> !(mustUseShield && w.getStats().isTwoHanded()))
			.collect(Collectors.toList());

		Candidate weapon = null;
		SlotRule requiredWeapon = setup.getRequired().get(EquipmentInventorySlot.WEAPON);
		if (requiredWeapon != null)
		{
			weapon = firstMatch(candidates(EquipmentInventorySlot.WEAPON), requiredWeapon.getNames(), this::weaponScore);
			if (weapon == null)
			{
				warnings.add("Missing required weapon: " + String.join(" / ", requiredWeapon.getNames()));
			}
		}
		if (weapon == null)
		{
			weapon = firstPreferred(weapons, EquipmentInventorySlot.WEAPON, this::weaponScore);
		}
		if (weapon == null)
		{
			// Compare the best two-hander against the best one-hander plus shield.
			double bestShield = best(candidates(EquipmentInventorySlot.SHIELD), this::score)
				.map(this::score).filter(s -> s > 0).orElse(0.0);
			Candidate best = null;
			double bestScore = 0;
			for (Candidate w : weapons)
			{
				double s = weaponScore(w) + (w.getStats().isTwoHanded() ? 0 : bestShield);
				if (best == null || s > bestScore || (s == bestScore && w.getSource().ordinal() < best.getSource().ordinal()))
				{
					best = w;
					bestScore = s;
				}
			}
			weapon = best;
		}

		if (weapon != null)
		{
			picks.put(EquipmentInventorySlot.WEAPON, weapon);
		}
		else if (requiredWeapon == null)
		{
			warnings.add("No " + style.getDisplayName().toLowerCase(Locale.ROOT) + " weapon found.");
		}

		if (weapon == null || !weapon.getStats().isTwoHanded())
		{
			pickSlot(EquipmentInventorySlot.SHIELD, candidates(EquipmentInventorySlot.SHIELD));
		}
		else if (requiredShield != null)
		{
			warnings.add("Missing required shield: " + String.join(" / ", requiredShield.getNames()));
		}
	}

	private boolean suitsStyle(Candidate w)
	{
		ItemEquipmentStats s = w.getStats();
		switch (style)
		{
			case RANGED:
				return s.getArange() > 0;
			case MAGIC:
				return s.getAmagic() > 0;
			default:
				return meleeAccuracy(s) > 0 || s.getStr() > 0;
		}
	}

	/** Weapon score includes the best compatible ammo and is scaled by attack speed (4 ticks = 1.0). */
	private double weaponScore(Candidate w)
	{
		double s = score(w);
		if (style == CombatStyle.RANGED)
		{
			s += bestAmmoFor(w).map(this::score).orElse(0.0);
		}
		int speed = w.getStats().getAspeed();
		return speed > 0 ? s * 4.0 / speed : s;
	}

	// ---------------------------------------------------------------- ammo

	private void pickAmmo()
	{
		Candidate weapon = picks.get(EquipmentInventorySlot.WEAPON);
		List<Candidate> ammo = candidates(EquipmentInventorySlot.AMMO).stream()
			.filter(ammoFilter(weapon))
			.collect(Collectors.toList());

		boolean picked = pickSlot(EquipmentInventorySlot.AMMO, ammo);
		if (!picked && weapon != null && style == CombatStyle.RANGED && !ammoWord(weapon).isEmpty())
		{
			warnings.add("No " + ammoWord(weapon) + "s found for " + weapon.getName() + ".");
		}
	}

	private Optional<Candidate> bestAmmoFor(Candidate weapon)
	{
		return best(candidates(EquipmentInventorySlot.AMMO).stream().filter(ammoFilter(weapon)).collect(Collectors.toList()), this::score);
	}

	/**
	 * Ranged weapons only accept matching projectiles; everything else (blowpipe, thrown weapons,
	 * crystal bows, melee, magic) can only use non-projectile ammo-slot items like blessings.
	 */
	private Predicate<Candidate> ammoFilter(Candidate weapon)
	{
		String word = (weapon != null && style == CombatStyle.RANGED) ? ammoWord(weapon) : "";
		switch (word)
		{
			case "":
				return a -> !isProjectile(a);
			case "ascension bolt":
				return a -> a.nameContains("ascension bolts");
			case "antler bolt":
				return a -> a.nameContains("antler bolts");
			case "bolt":
			{
				boolean dragonBolts = containsAny(weapon, DRAGON_BOLT_CROSSBOWS);
				return a -> a.nameContains("bolts") && !a.nameContains("bolt rack") && !a.nameContains("ascension")
					&& !a.nameContains("antler") && (dragonBolts || !a.nameContains("dragon bolts"));
			}
			case "arrow":
			{
				boolean dragonArrows = containsAny(weapon, DRAGON_ARROW_BOWS);
				return a -> a.nameContains("arrow") && (dragonArrows || !a.nameContains("dragon arrow"));
			}
			default:
				return a -> a.nameContains(word);
		}
	}

	static String ammoWord(Candidate weapon)
	{
		String n = weapon.getName().toLowerCase(Locale.ROOT);
		if (n.contains("ballista"))
		{
			return "javelin";
		}
		if (n.contains("karil's crossbow"))
		{
			return "bolt rack";
		}
		if (n.contains("ascension crossbow"))
		{
			return "ascension bolt";
		}
		if (n.contains("sunlight crossbow"))
		{
			return "antler bolt";
		}
		if (n.contains("atlatl"))
		{
			return "atlatl dart";
		}
		if (n.contains("craw's bow") || n.contains("webweaver bow"))
		{
			return "";
		}
		if (n.contains("crossbow"))
		{
			return "bolt";
		}
		if (n.contains("crystal bow") || n.contains("bow of faerdhinen") || n.contains("blowpipe"))
		{
			return "";
		}
		if (n.contains("bow"))
		{
			return "arrow";
		}
		return "";
	}

	private static boolean usesCrystalArmour(Candidate weapon)
	{
		return weapon.nameContains("Bow of faerdhinen") || weapon.nameContains("Crystal bow");
	}

	private static boolean containsAny(Candidate c, String[] fragments)
	{
		for (String f : fragments)
		{
			if (c.nameContains(f))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isProjectile(Candidate c)
	{
		for (String word : PROJECTILE_WORDS)
		{
			if (c.nameContains(word))
			{
				return true;
			}
		}
		return false;
	}

	// ---------------------------------------------------------------- generic slots

	/** Fills a slot from the given options. Returns true if something was picked. */
	private boolean pickSlot(EquipmentInventorySlot slot, List<Candidate> options)
	{
		Candidate weapon = picks.get(EquipmentInventorySlot.WEAPON);
		if (weapon == null || !usesCrystalArmour(weapon))
		{
			// Crystal armour's bonus only applies with crystal bows; otherwise it's just weak armour.
			options = options.stream()
				.filter(c -> CRYSTAL_ARMOUR.stream().noneMatch(c::nameContains))
				.collect(Collectors.toList());
		}
		if (slot == EquipmentInventorySlot.SHIELD && (weapon == null || containsAny(weapon, POWERED_STAVES)))
		{
			// Elemental tomes only boost standard spells, which powered staves can't cast.
			options = options.stream().filter(c -> !c.nameContains("Tome of")).collect(Collectors.toList());
		}
		SlotRule required = setup.getRequired().get(slot);
		Candidate pick;
		if (required != null)
		{
			pick = firstMatch(options, required.getNames(), this::score);
			if (pick == null)
			{
				warnings.add("Missing required " + slotName(slot) + ": " + String.join(" / ", required.getNames()));
				return false;
			}
		}
		else
		{
			pick = firstPreferred(options, slot, this::score);
			if (pick == null)
			{
				pick = best(options, this::score).filter(c -> score(c) > 0).orElse(null);
			}
		}
		if (pick != null)
		{
			picks.put(slot, pick);
			return true;
		}
		return false;
	}

	// ---------------------------------------------------------------- helpers

	private List<Candidate> candidates(EquipmentInventorySlot slot)
	{
		return bySlot.getOrDefault(slot.getSlotIdx(), Collections.emptyList());
	}

	/** The first name in the list the player owns; among several matching variants, the highest scoring. */
	private static Candidate firstMatch(List<Candidate> options, List<String> names, ToDoubleFunction<Candidate> scorer)
	{
		for (String name : names)
		{
			List<Candidate> matches = options.stream().filter(c -> c.nameContains(name)).collect(Collectors.toList());
			Optional<Candidate> b = best(matches, scorer);
			if (b.isPresent())
			{
				return b.get();
			}
		}
		return null;
	}

	private static Optional<Candidate> best(List<Candidate> options, ToDoubleFunction<Candidate> scorer)
	{
		return options.stream().max(Comparator
			.comparingDouble(scorer)
			.thenComparing(c -> -c.getSource().ordinal()));
	}

	/** Linear stat score for the setup's style. Higher is better. */
	double score(Candidate c)
	{
		ItemEquipmentStats s = c.getStats();
		double defence = (s.getDstab() + s.getDslash() + s.getDcrush() + s.getDmagic() + s.getDrange()) * 0.01;
		double prayer = s.getPrayer() * 0.1;
		switch (style)
		{
			case RANGED:
				return s.getRstr() * 1.2 + s.getArange() * 0.5 + prayer + defence;
			case MAGIC:
				return s.getMdmg() * 3.0 + s.getAmagic() * 0.6 + prayer + defence;
			default:
				return s.getStr() * 1.0 + meleeAccuracy(s) * 0.5 + prayer + defence;
		}
	}

	private int meleeAccuracy(ItemEquipmentStats s)
	{
		switch (style)
		{
			case STAB:
				return s.getAstab();
			case SLASH:
				return s.getAslash();
			case CRUSH:
				return s.getAcrush();
			default:
				return Math.max(s.getAstab(), Math.max(s.getAslash(), s.getAcrush()));
		}
	}

	private static String slotName(EquipmentInventorySlot slot)
	{
		String n = slot.name().toLowerCase(Locale.ROOT);
		return n.equals("amulet") ? "neck item" : n;
	}
}

package com.gearmeup;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(GearMeUpConfig.GROUP)
public interface GearMeUpConfig extends Config
{
	String GROUP = "gearmeup";

	@ConfigItem(
		keyName = "includeBank",
		name = "Include bank",
		description = "Use items from your bank. Open your bank once so the plugin can remember what's in it.",
		position = 1
	)
	default boolean includeBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeInventory",
		name = "Include inventory",
		description = "Use items currently in your inventory.",
		position = 2
	)
	default boolean includeInventory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "ignoredItems",
		name = "Ignored items",
		description = "Comma-separated item names (or parts of names) never to recommend, e.g. 'Dharok, Void'.",
		position = 3
	)
	default String ignoredItems()
	{
		return "";
	}
}

package com.gearmeup;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.JToggleButton;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/**
 * Side panel: choose a boss (and setup), press the button, see one row per equipment slot.
 */
class GearMeUpPanel extends PluginPanel
{
	private static final Color WARNING = new Color(0xFF6B6B);

	private final GearMeUpPlugin plugin;
	private final ItemManager itemManager;

	private static final String ALL = "All bosses";

	private final List<Boss> bosses;
	private final IconTextField searchField = new IconTextField();
	private final JComboBox<String> categoryBox = new JComboBox<>();
	private final JComboBox<Boss> bossBox = new JComboBox<>();
	private final JComboBox<GearSetup> setupBox = new JComboBox<>();
	private final JCheckBox slayerBox = new JCheckBox("On slayer task");
	private final JPanel results = new JPanel();

	private static final String BANK_FILTER_OFF = "Show only this gear in bank";
	private static final String BANK_FILTER_ON = "Bank filtered (click to stop)";
	private final JToggleButton bankFilter = new JToggleButton(BANK_FILTER_OFF);

	GearMeUpPanel(GearMeUpPlugin plugin, ItemManager itemManager, List<Boss> bosses)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.bosses = bosses;

		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JPanel controls = new JPanel(new GridLayout(0, 1, 0, 6));

		JLabel title = new JLabel("Gear Me Up");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setHorizontalAlignment(SwingConstants.CENTER);
		controls.add(title);

		controls.add(smallLabel("Search boss"));
		searchField.setIcon(IconTextField.Icon.SEARCH);
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchField.setToolTipText("Type a boss name or nickname (e.g. kq, cerb, tob). Enter gears you up.");
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				refreshBosses();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				refreshBosses();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				refreshBosses();
			}
		});
		searchField.addClearListener(this::refreshBosses);
		searchField.addActionListener(e -> gearUp());
		controls.add(searchField);

		controls.add(smallLabel("Category"));
		Set<String> categories = new LinkedHashSet<>();
		categories.add(ALL);
		bosses.forEach(b -> categories.add(b.getCategory()));
		categories.forEach(categoryBox::addItem);
		categoryBox.addActionListener(e -> refreshBosses());
		controls.add(categoryBox);

		controls.add(smallLabel("Boss"));
		bossBox.addActionListener(e -> refreshSetups());
		controls.add(bossBox);

		controls.add(smallLabel("Setup"));
		controls.add(setupBox);

		slayerBox.setToolTipText("Prefer your slayer helmet / black mask (only works on a slayer task)");
		controls.add(slayerBox);

		JButton go = new JButton("Gear me up!");
		go.addActionListener(e -> gearUp());
		controls.add(go);

		bankFilter.setToolTipText("Filter the bank so it only shows the suggested items. Applies whenever the bank is open.");
		bankFilter.setEnabled(false);
		bankFilter.addActionListener(e ->
		{
			boolean on = bankFilter.isSelected();
			bankFilter.setText(on ? BANK_FILTER_ON : BANK_FILTER_OFF);
			plugin.setBankFilter(on);
		});
		controls.add(bankFilter);

		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		results.setBorder(new EmptyBorder(10, 0, 0, 0));
		refreshBosses();

		add(controls, BorderLayout.NORTH);
		add(results, BorderLayout.CENTER);
	}

	private void refreshBosses()
	{
		String query = searchField.getText() == null ? "" : searchField.getText().trim();
		// A search looks through every category; otherwise the category picker applies.
		String category = query.isEmpty() ? (String) categoryBox.getSelectedItem() : ALL;
		Boss previous = (Boss) bossBox.getSelectedItem();
		DefaultComboBoxModel<Boss> model = new DefaultComboBoxModel<>();
		bosses.stream()
			.filter(b -> ALL.equals(category) || b.getCategory().equals(category))
			.filter(b -> b.matches(query))
			.sorted((a, b) ->
			{
				// Best matches first when searching, then alphabetical.
				int byRank = query.isEmpty() ? 0 : Integer.compare(a.matchRank(query), b.matchRank(query));
				return byRank != 0 ? byRank : a.getName().compareToIgnoreCase(b.getName());
			})
			.forEach(model::addElement);
		bossBox.setModel(model);
		categoryBox.setEnabled(query.isEmpty());
		if (previous != null && model.getIndexOf(previous) >= 0 && query.isEmpty())
		{
			bossBox.setSelectedItem(previous);
		}
		if (model.getSize() == 0)
		{
			setupBox.setModel(new DefaultComboBoxModel<>());
			setupBox.setEnabled(false);
			results.removeAll();
			results.add(wrappingText("No boss matches \"" + query + "\". Try another name, or use \"Any monster (generic)\" "
				+ "and pick the style your target is weakest to.", ColorScheme.LIGHT_GRAY_COLOR));
			results.revalidate();
			results.repaint();
			return;
		}
		refreshSetups();
	}

	private void refreshSetups()
	{
		Boss boss = (Boss) bossBox.getSelectedItem();
		DefaultComboBoxModel<GearSetup> model = new DefaultComboBoxModel<>();
		if (boss != null)
		{
			for (GearSetup s : boss.getSetups())
			{
				model.addElement(s);
			}
		}
		setupBox.setModel(model);
		setupBox.setRenderer(new javax.swing.DefaultListCellRenderer()
		{
			@Override
			public java.awt.Component getListCellRendererComponent(javax.swing.JList<?> list, Object value, int index, boolean selected, boolean focus)
			{
				Object text = value instanceof GearSetup ? ((GearSetup) value).getLabel() : value;
				return super.getListCellRendererComponent(list, text, index, selected, focus);
			}
		});
		setupBox.setEnabled(model.getSize() > 1);

		results.removeAll();
		if (boss != null && !boss.describe().isEmpty())
		{
			results.add(wrappingText(boss.describe(), ColorScheme.LIGHT_GRAY_COLOR));
			results.add(spacer(8));
		}
		results.add(wrappingText("Press \"Gear me up!\" to see your best setup. Open your bank once so your banked gear is included.",
			ColorScheme.MEDIUM_GRAY_COLOR));
		results.revalidate();
		results.repaint();
	}

	private void gearUp()
	{
		GearSetup setup = (GearSetup) setupBox.getSelectedItem();
		if (setup != null)
		{
			showMessage("Working it out...");
			plugin.gearUp(setup, slayerBox.isSelected());
		}
	}

	void showMessage(String message)
	{
		results.removeAll();
		results.add(wrappingText(message, ColorScheme.LIGHT_GRAY_COLOR));
		results.revalidate();
		results.repaint();
	}

	void showResult(GearResult result, SpellAdvice spell, String bankStatus)
	{
		results.removeAll();
		bankFilter.setEnabled(true);

		JLabel heading = new JLabel(result.getSetup().toString());
		heading.setFont(FontManager.getRunescapeBoldFont());
		heading.setForeground(ColorScheme.BRAND_ORANGE);
		heading.setAlignmentX(LEFT_ALIGNMENT);
		results.add(heading);
		Boss boss = result.getSetup().getBoss();
		if (boss != null && !boss.describe().isEmpty())
		{
			results.add(spacer(2));
			results.add(wrappingText(boss.describe(), ColorScheme.LIGHT_GRAY_COLOR));
		}
		results.add(spacer(6));

		for (EquipmentInventorySlot slot : GearCalculator.SLOTS)
		{
			results.add(slotRow(slot, result.get(slot)));
			results.add(spacer(3));
		}

		if (spell != null)
		{
			results.add(spacer(8));
			results.add(spellSection(spell));
		}

		for (String warning : result.getWarnings())
		{
			results.add(spacer(4));
			results.add(wrappingText("! " + warning, WARNING));
		}

		if (!result.getSetup().getNotes().isEmpty())
		{
			results.add(spacer(8));
			results.add(smallLabel("Tips"));
			results.add(wrappingText(result.getSetup().getNotes(), ColorScheme.LIGHT_GRAY_COLOR));
		}

		results.add(spacer(8));
		results.add(wrappingText(bankStatus, ColorScheme.MEDIUM_GRAY_COLOR));

		results.revalidate();
		results.repaint();
	}

	private JPanel spellSection(SpellAdvice spell)
	{
		JPanel box = new JPanel();
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		box.setAlignmentX(LEFT_ALIGNMENT);

		JLabel header = new JLabel(spell.isCharges() ? "Recharging" : "Spell to autocast");
		header.setFont(FontManager.getRunescapeSmallFont());
		header.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		header.setAlignmentX(LEFT_ALIGNMENT);
		box.add(header);

		JTextArea title = wrappingText(spell.getTitle(), Color.WHITE);
		box.add(title);
		box.add(spacer(4));

		JLabel per = new JLabel(spell.isCharges() ? "Per charge:" : "Runes per cast:");
		per.setFont(FontManager.getRunescapeSmallFont());
		per.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		per.setAlignmentX(LEFT_ALIGNMENT);
		box.add(per);

		for (SpellAdvice.Line line : spell.getLines())
		{
			String text;
			Color color;
			if (line.isFree())
			{
				text = line.getPerCast() + " x " + line.getItem() + " - free (staff/tome)";
				color = ItemSource.EQUIPPED.getColor();
			}
			else
			{
				text = line.getPerCast() + " x " + line.getItem() + " - have " + String.format("%,d", line.getHave());
				color = line.getHave() >= line.getPerCast() ? Color.WHITE : WARNING;
			}
			box.add(wrappingText(text, color));
		}

		if (spell.getCasts() >= 0)
		{
			box.add(spacer(4));
			String what = spell.isCharges() ? "charges" : "casts";
			box.add(wrappingText("Enough for about " + String.format("%,d", spell.getCasts()) + " " + what + ".",
				spell.getCasts() > 0 ? ColorScheme.LIGHT_GRAY_COLOR : WARNING));
		}
		for (String note : spell.getNotes())
		{
			box.add(spacer(2));
			box.add(wrappingText(note, ColorScheme.MEDIUM_GRAY_COLOR));
		}
		return box;
	}

	private JPanel slotRow(EquipmentInventorySlot slot, Candidate pick)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (pick != null)
		{
			itemManager.getImage(pick.getItemId()).addTo(icon);
		}
		row.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel(new GridLayout(0, 1));
		text.setOpaque(false);

		JLabel slotName = new JLabel(slotDisplayName(slot));
		slotName.setFont(FontManager.getRunescapeSmallFont());
		slotName.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		text.add(slotName);

		JLabel itemName = new JLabel(pick == null ? "Nothing suitable" : pick.getName());
		itemName.setForeground(pick == null ? ColorScheme.MEDIUM_GRAY_COLOR : Color.WHITE);
		itemName.setFont(FontManager.getRunescapeSmallFont());
		text.add(itemName);

		if (pick != null)
		{
			itemName.setToolTipText(pick.getName() + " (" + pick.getSource().getDisplayName() + ")");
			JLabel source = new JLabel(pick.getSource().getDisplayName());
			source.setFont(FontManager.getRunescapeSmallFont());
			source.setForeground(pick.getSource().getColor());
			text.add(source);
		}

		row.add(text, BorderLayout.CENTER);
		return row;
	}

	private static String slotDisplayName(EquipmentInventorySlot slot)
	{
		switch (slot)
		{
			case AMULET:
				return "Neck";
			case GLOVES:
				return "Hands";
			case BOOTS:
				return "Feet";
			default:
				String n = slot.name().toLowerCase();
				return Character.toUpperCase(n.charAt(0)) + n.substring(1);
		}
	}

	private static JLabel smallLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	private static JTextArea wrappingText(String text, Color color)
	{
		JTextArea area = new JTextArea(text);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setEditable(false);
		area.setFocusable(false);
		area.setOpaque(false);
		area.setForeground(color);
		area.setFont(FontManager.getRunescapeSmallFont());
		area.setAlignmentX(LEFT_ALIGNMENT);
		area.setBorder(null);
		return area;
	}

	private static JPanel spacer(int height)
	{
		JPanel p = new JPanel();
		p.setOpaque(false);
		p.setAlignmentX(LEFT_ALIGNMENT);
		p.setPreferredSize(new Dimension(0, height));
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return p;
	}
}

package com.gearmeup;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import net.runelite.api.EquipmentInventorySlot;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Gear Me Up",
	description = "Pick a boss and get the best gear setup from what you own (bank, inventory and equipped)",
	tags = {"gear", "setup", "boss", "pvm", "equipment", "bank", "loadout"}
)
@PluginDependency(BankTagsPlugin.class)
public class GearMeUpPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(GearMeUpPlugin.class);
	private static final String BANK_KEY = "bankItems";


	/** Bank tag (provided in code, never saved) that matches only the suggested items. */
	private static final String BANK_TAG = "gear me up";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private GearMeUpConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Gson gson;

	@Inject
	private TagManager tagManager;

	@Inject
	private BankTagsService bankTagsService;

	private GearMeUpPanel panel;
	private BossData bossData;
	private NavigationButton navButton;

	/** Item id -> quantity last seen in the bank (null = not loaded for this profile yet). Client thread only. */
	private Map<Integer, Long> bankItems;
	private SpellAdvisor spellAdvisor;
	private int lastMagicLevel = -1;
	private volatile GearSetup selectedSetup;
	private volatile boolean onSlayerTask;

	/** Item ids in the current suggestion, used by the bank filter. */
	private volatile Set<Integer> suggestedIds = Collections.emptySet();
	private volatile boolean bankFilterOn;

	@Provides
	GearMeUpConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GearMeUpConfig.class);
	}

	@Override
	protected void startUp()
	{
		try
		{
			bossData = BossData.load(gson);
			spellAdvisor = new SpellAdvisor(SpellData.load(gson));
		}
		catch (IOException | RuntimeException e)
		{
			log.error("Gear Me Up: couldn't load its data files", e);
			throw new IllegalStateException("Gear Me Up couldn't load its boss list", e);
		}
		panel = new GearMeUpPanel(this, itemManager, bossData.getBosses());
		navButton = NavigationButton.builder()
			.tooltip("Gear Me Up")
			.icon(createIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		tagManager.registerTag(BANK_TAG, itemId -> suggestedIds.contains(itemId));
	}

	@Override
	protected void shutDown()
	{
		bankFilterOn = false;
		clientThread.invokeLater(this::closeBankFilter);
		tagManager.unregisterTag(BANK_TAG);
		suggestedIds = Collections.emptySet();
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		bankItems = null;
		selectedSetup = null;
	}

	/** Called from the panel (Swing thread) when the player presses "Gear me up!". */
	void gearUp(GearSetup setup, boolean slayerTask)
	{
		selectedSetup = setup;
		onSlayerTask = slayerTask;
		clientThread.invokeLater(this::recalculate);
	}

	/** Called from the panel: show only the suggested items in the bank (now, and whenever it's opened). */
	void setBankFilter(boolean on)
	{
		bankFilterOn = on;
		clientThread.invokeLater(on ? this::applyBankFilter : this::closeBankFilter);
	}

	/** Client thread. Opens our tag if the bank is open; otherwise it's applied when the bank next opens. */
	private void applyBankFilter()
	{
		if (bankFilterOn && client.getWidget(InterfaceID.Bankmain.ITEMS) != null)
		{
			bankTagsService.openBankTag(BANK_TAG, BankTagsService.OPTION_NO_LAYOUT);
		}
	}

	private void closeBankFilter()
	{
		if (BANK_TAG.equals(bankTagsService.getActiveTag()))
		{
			bankTagsService.closeBankTag();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && bankFilterOn)
		{
			// Wait until the bank has finished building before filtering it.
			clientThread.invokeLater(this::applyBankFilter);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			Map<Integer, Long> items = new TreeMap<>();
			for (Item i : event.getItemContainer().getItems())
			{
				if (i.getId() > 0 && i.getQuantity() > 0)
				{
					items.merge(i.getId(), (long) i.getQuantity(), Long::sum);
				}
			}
			if (items.equals(bankItems))
			{
				return; // nothing changed (e.g. just moving items around)
			}
			bankItems = items;
			configManager.setRSProfileConfiguration(GearMeUpConfig.GROUP, BANK_KEY,
				items.entrySet().stream().map(e -> e.getKey() + ":" + e.getValue()).collect(Collectors.joining(",")));
		}
		else if (id != InventoryID.INV && id != InventoryID.WORN)
		{
			return;
		}

		if (selectedSetup != null)
		{
			recalculate();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.SPELLBOOK && isMagicSetup())
		{
			recalculate();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// Only on a level change, not every XP drop.
		if (event.getSkill() == Skill.MAGIC && event.getLevel() != lastMagicLevel)
		{
			lastMagicLevel = event.getLevel();
			if (isMagicSetup())
			{
				recalculate();
			}
		}
	}

	private boolean isMagicSetup()
	{
		GearSetup s = selectedSetup;
		return s != null && s.getStyle() == CombatStyle.MAGIC;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			// May be a different account: reload the bank snapshot for this profile.
			bankItems = null;
			if (selectedSetup != null)
			{
				recalculate();
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (GearMeUpConfig.GROUP.equals(event.getGroup()) && !BANK_KEY.equals(event.getKey()) && selectedSetup != null)
		{
			clientThread.invokeLater(this::recalculate);
		}
	}

	/** Gathers owned gear and works out the setup. Must run on the client thread. */
	private void recalculate()
	{
		GearSetup setup = selectedSetup;
		GearMeUpPanel p = panel;
		if (setup == null || p == null)
		{
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			SwingUtilities.invokeLater(() -> p.showMessage("Log in to see gear for " + setup + "."));
			return;
		}

		Map<Integer, Candidate> owned = new HashMap<>();
		Map<String, Long> quantities = new HashMap<>();
		addContainer(InventoryID.WORN, ItemSource.EQUIPPED, owned, quantities);
		if (config.includeInventory())
		{
			addContainer(InventoryID.INV, ItemSource.INVENTORY, owned, quantities);
		}

		String bankStatus;
		if (config.includeBank())
		{
			Map<Integer, Long> bank = loadBank();
			if (bank == null)
			{
				bankStatus = "Bank not seen yet: open your bank once to include it.";
			}
			else
			{
				bank.forEach((itemId, qty) -> addItem(itemId, qty, ItemSource.BANK, owned, quantities));
				bankStatus = "Bank remembered (" + bank.size() + " items). Open it to refresh.";
			}
		}
		else
		{
			bankStatus = "Bank items are turned off in the plugin settings.";
		}

		GearResult result = GearCalculator.calculate(setup, owned.values(), onSlayerTask, ignoredNames(), bossData.getKnowledge());

		Set<Integer> ids = new HashSet<>();
		result.getPicks().values().forEach(c -> ids.add(c.getItemId()));
		if (!ids.equals(suggestedIds))
		{
			suggestedIds = Collections.unmodifiableSet(ids);
			if (BANK_TAG.equals(bankTagsService.getActiveTag()))
			{
				applyBankFilter(); // refresh the filtered bank view
			}
		}
		SpellAdvice spell = null;
		if (setup.getStyle() == CombatStyle.MAGIC)
		{
			spell = spellAdvisor.advise(result.get(EquipmentInventorySlot.WEAPON), result.get(EquipmentInventorySlot.SHIELD),
				setup.getBoss(), client.getRealSkillLevel(Skill.MAGIC), client.getVarbitValue(VarbitID.SPELLBOOK), quantities);
		}
		SpellAdvice spellAdvice = spell;
		SwingUtilities.invokeLater(() -> p.showResult(result, spellAdvice, bankStatus));
	}

	private void addContainer(int id, ItemSource source, Map<Integer, Candidate> owned, Map<String, Long> quantities)
	{
		ItemContainer container = client.getItemContainer(id);
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				addItem(item.getId(), item.getQuantity(), source, owned, quantities);
			}
		}
	}

	private void addItem(int itemId, long quantity, ItemSource source, Map<Integer, Candidate> owned, Map<String, Long> quantities)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		if (comp.getPlaceholderTemplateId() != -1)
		{
			return; // bank placeholder: not actually owned
		}
		if (comp.getNote() != -1)
		{
			itemId = comp.getLinkedNoteId(); // noted item: use the unnoted version
			comp = itemManager.getItemComposition(itemId);
		}
		quantities.merge(comp.getName(), quantity, Long::sum); // used for rune counts

		ItemStats stats = itemManager.getItemStats(itemId);
		if (stats == null || !stats.isEquipable() || stats.getEquipment() == null)
		{
			return;
		}

		Candidate existing = owned.get(itemId);
		if (existing == null || source.ordinal() < existing.getSource().ordinal())
		{
			owned.put(itemId, new Candidate(itemId, comp.getName(), source, stats.getEquipment()));
		}
	}

	/** Saved as "id:qty,id:qty". Older saves without quantities ("id,id") count as 1 each. */
	private Map<Integer, Long> loadBank()
	{
		if (bankItems == null)
		{
			String saved = configManager.getRSProfileConfiguration(GearMeUpConfig.GROUP, BANK_KEY);
			if (saved == null || saved.isEmpty())
			{
				return null;
			}
			try
			{
				Map<Integer, Long> items = new TreeMap<>();
				for (String entry : saved.split(","))
				{
					String[] parts = entry.split(":");
					items.put(Integer.parseInt(parts[0]), parts.length > 1 ? Long.parseLong(parts[1]) : 1L);
				}
				bankItems = items;
			}
			catch (NumberFormatException e)
			{
				return null;
			}
		}
		return bankItems;
	}

	private List<String> ignoredNames()
	{
		String raw = config.ignoredItems();
		if (raw == null || raw.trim().isEmpty())
		{
			return Collections.emptyList();
		}
		return Arrays.stream(raw.split(","))
			.map(String::trim)
			.filter(s -> !s.isEmpty())
			.collect(Collectors.toList());
	}

	/** Small helmet icon drawn in code so the plugin needs no image resources. */
	private static BufferedImage createIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xB0BEC5));
		g.fillArc(2, 2, 12, 14, 0, 180);
		g.fillRect(2, 8, 12, 5);
		g.setColor(new Color(0x37474F));
		g.fillRect(4, 9, 8, 2);
		g.setStroke(new BasicStroke(1.5f));
		g.setColor(new Color(0xFF9800));
		g.drawLine(8, 1, 8, 5);
		g.dispose();
		return img;
	}
}

package com.gearmeup;

import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;

/**
 * The recommended setup: one owned item per slot (or none), plus warnings such as missing
 * required items.
 */
public final class GearResult
{
	private final GearSetup setup;
	private final Map<EquipmentInventorySlot, Candidate> picks;
	private final List<String> warnings;

	GearResult(GearSetup setup, Map<EquipmentInventorySlot, Candidate> picks, List<String> warnings)
	{
		this.setup = setup;
		this.picks = Collections.unmodifiableMap(new EnumMap<>(picks));
		this.warnings = Collections.unmodifiableList(warnings);
	}

	public GearSetup getSetup()
	{
		return setup;
	}

	public Candidate get(EquipmentInventorySlot slot)
	{
		return picks.get(slot);
	}

	public Map<EquipmentInventorySlot, Candidate> getPicks()
	{
		return picks;
	}

	public List<String> getWarnings()
	{
		return warnings;
	}
}

package com.gearmeup;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;

/**
 * One way to fight a boss (e.g. "Zulrah - Magic"): a combat style, per-slot item preferences
 * and requirements, and tips.
 */
public final class GearSetup
{
	private final String label;
	private final CombatStyle style;
	private final Map<EquipmentInventorySlot, SlotRule> preferred;
	private final Map<EquipmentInventorySlot, SlotRule> required;
	private final String notes;
	private Boss boss;

	GearSetup(String label, CombatStyle style, Map<EquipmentInventorySlot, SlotRule> preferred,
		Map<EquipmentInventorySlot, SlotRule> required, String notes)
	{
		this.label = label == null || label.isEmpty() ? style.getDisplayName() : label;
		this.style = style;
		this.preferred = Collections.unmodifiableMap(copy(preferred));
		this.required = Collections.unmodifiableMap(copy(required));
		this.notes = notes;
	}

	private static Map<EquipmentInventorySlot, SlotRule> copy(Map<EquipmentInventorySlot, SlotRule> m)
	{
		Map<EquipmentInventorySlot, SlotRule> out = new EnumMap<>(EquipmentInventorySlot.class);
		out.putAll(m);
		return out;
	}

	void setBoss(Boss boss)
	{
		this.boss = boss;
	}

	public Boss getBoss()
	{
		return boss;
	}

	public String getLabel()
	{
		return label;
	}

	public CombatStyle getStyle()
	{
		return style;
	}

	public Map<EquipmentInventorySlot, SlotRule> getPreferred()
	{
		return preferred;
	}

	public Map<EquipmentInventorySlot, SlotRule> getRequired()
	{
		return required;
	}

	public String getNotes()
	{
		return notes;
	}

	@Override
	public String toString()
	{
		return boss == null ? label : boss.getName() + " - " + label;
	}
}

package com.gearmeup;

import java.awt.Color;

/**
 * Where an owned item currently is. Lower ordinal = more convenient, so it wins when the
 * same item is found in several places.
 */
public enum ItemSource
{
	EQUIPPED("Equipped", new Color(0x4CAF50)),
	INVENTORY("Inventory", new Color(0xFFC107)),
	BANK("Bank", new Color(0xFF9800));

	private final String displayName;
	private final Color color;

	ItemSource(String displayName, Color color)
	{
		this.displayName = displayName;
		this.color = color;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public Color getColor()
	{
		return color;
	}
}

package com.gearmeup;

import java.util.Collections;
import java.util.List;

/**
 * An ordered list of item name fragments (best first) for one slot. If {@code required}, the slot
 * must hold one of them and the result warns when the player owns none.
 */
public final class SlotRule
{
	private final List<String> names;
	private final boolean required;

	SlotRule(List<String> names, boolean required)
	{
		this.names = Collections.unmodifiableList(names);
		this.required = required;
	}

	public List<String> getNames()
	{
		return names;
	}

	public boolean isRequired()
	{
		return required;
	}
}

package com.gearmeup;

import java.util.Collections;
import java.util.List;

/**
 * What to cast (or what the weapon's charges cost) and the runes involved.
 */
public final class SpellAdvice
{
	/** One rune (or other item) needed per cast / per charge. */
	public static final class Line
	{
		private final String item;
		private final int perCast;
		private final boolean free;
		private final long have;

		Line(String item, int perCast, boolean free, long have)
		{
			this.item = item;
			this.perCast = perCast;
			this.free = free;
			this.have = have;
		}

		public String getItem()
		{
			return item;
		}

		public int getPerCast()
		{
			return perCast;
		}

		/** Supplied by the equipped staff or tome, so none are needed. */
		public boolean isFree()
		{
			return free;
		}

		public long getHave()
		{
			return have;
		}
	}

	private final String title;
	private final boolean charges;
	private final List<Line> lines;
	private final long casts;
	private final List<String> notes;

	SpellAdvice(String title, boolean charges, List<Line> lines, long casts, List<String> notes)
	{
		this.title = title;
		this.charges = charges;
		this.lines = Collections.unmodifiableList(lines);
		this.casts = casts;
		this.notes = Collections.unmodifiableList(notes);
	}

	/** e.g. "Fire Surge (Standard, level 95)" or "Trident of the swamp charges". */
	public String getTitle()
	{
		return title;
	}

	/** True when the lines are the cost of one weapon charge rather than one spell cast. */
	public boolean isCharges()
	{
		return charges;
	}

	public List<Line> getLines()
	{
		return lines;
	}

	/** How many casts (or charges) the owned runes cover; -1 if unlimited. */
	public long getCasts()
	{
		return casts;
	}

	public List<String> getNotes()
	{
		return notes;
	}
}

package com.gearmeup;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Picks the spell to autocast with the suggested magic weapon (or, for powered staves, shows what a
 * charge costs) and works out the runes needed and how many the player owns. Pure logic.
 */
public final class SpellAdvisor
{
	public static final int BOOK_STANDARD = 0;
	public static final int BOOK_ANCIENT = 1;
	public static final int BOOK_LUNAR = 2;
	public static final int BOOK_ARCEUUS = 3;

	private final SpellData data;

	public SpellAdvisor(SpellData data)
	{
		this.data = data;
	}

	/**
	 * @param weapon      suggested weapon (null = nothing to advise)
	 * @param shield      suggested shield (tomes can supply runes)
	 * @param boss        the boss (for elemental weakness and demon type); may be null
	 * @param magicLevel  the player's Magic level
	 * @param spellbook   current spellbook (BOOK_*), or -1 if unknown
	 * @param owned       item name (any case/spacing) -> quantity owned across bank, inventory and equipment
	 */
	public SpellAdvice advise(Candidate weapon, Candidate shield, Boss boss, int magicLevel, int spellbook, Map<String, Long> owned)
	{
		if (weapon == null)
		{
			return null;
		}
		Map<String, Long> have = normaliseKeys(owned);

		// Powered staves and charged weapons: show what one charge costs.
		for (SpellData.ChargedWeapon cw : data.chargedWeapons)
		{
			if (weapon.nameContains(cw.name))
			{
				List<String> notes = new ArrayList<>();
				notes.add("Uses its own built-in spell, so no spell to pick. The runes shown recharge it.");
				if (cw.notes != null && !cw.notes.isEmpty())
				{
					notes.add(cw.notes);
				}
				return build(cw.name + " charges", true, cw.perCharge, new HashSet<>(), have, notes);
			}
		}

		String weakness = boss == null ? null : boss.getElementalWeakness();
		int weakPercent = boss == null ? 0 : boss.getElementalWeaknessPercent();
		boolean demon = boss != null && boss.getAttributes().contains("demon");

		SpellData.Spell spell = null;
		String book = "standard";
		if (demon && listContains(data.autocastArceuus, weapon))
		{
			spell = best(magicLevel, "arceuus", null, 0, true);
			book = "arceuus";
		}
		// The Harmonised nightmare staff is standard-only, even though its name contains "Nightmare staff".
		boolean ancients = listContains(data.autocastAncients, weapon) && !weapon.nameContains("Harmonised");
		if (spell == null && spellbook == BOOK_ANCIENT && ancients)
		{
			spell = best(magicLevel, "ancient", null, 0, false);
			book = "ancient";
		}
		if (spell == null)
		{
			spell = best(magicLevel, "standard", weakness, weakPercent, false);
			book = "standard";
		}
		if (spell == null)
		{
			return null;
		}

		List<String> notes = new ArrayList<>();
		if (spell.element != null && spell.element.equalsIgnoreCase(weakness == null ? "" : weakness))
		{
			notes.add("Uses the boss's " + weakness + " weakness (+" + weakPercent + "% accuracy and damage).");
		}
		int wantBook = bookId(book);
		if (spellbook >= 0 && spellbook != wantBook)
		{
			notes.add("Switch to the " + capitalise(book) + " spellbook to cast this.");
		}
		if (spell.notes != null && !spell.notes.isEmpty())
		{
			notes.add(spell.notes);
		}
		notes.add("Runes in your rune pouch aren't counted.");

		Set<String> free = freeRunes(weapon, shield);
		String title = spell.name + " (" + capitalise(book) + ", level " + spell.level
			+ (spell.maxHit > 0 ? ", max hit up to " + spell.maxHit : "") + ")";
		return build(title, false, spell.runes, free, have, notes);
	}

	/** Highest-value spell of a book the player can cast. Elemental weakness boosts matching spells. */
	private SpellData.Spell best(int magicLevel, String book, String weakness, int weakPercent, boolean demonbaneOnly)
	{
		SpellData.Spell best = null;
		double bestValue = -1;
		for (SpellData.Spell s : data.spells)
		{
			if (s.book == null || !s.book.equalsIgnoreCase(book) || s.level > magicLevel || s.runes == null)
			{
				continue;
			}
			if (demonbaneOnly && !s.name.toLowerCase(Locale.ROOT).contains("demonbane"))
			{
				continue;
			}
			// Standard book: only the elemental Strike/Bolt/Blast/Wave/Surge line.
			if (book.equals("standard") && (s.element == null || s.element.isEmpty() || s.element.equals("null")))
			{
				continue;
			}
			double value = s.maxHit;
			if (weakness != null && weakness.equalsIgnoreCase(s.element))
			{
				value *= 1 + weakPercent / 100.0;
			}
			if (best == null || value > bestValue || (value == bestValue && s.level > best.level))
			{
				best = s;
				bestValue = value;
			}
		}
		return best;
	}

	private SpellAdvice build(String title, boolean charges, Map<String, Integer> costs, Set<String> free,
		Map<String, Long> have, List<String> notes)
	{
		List<SpellAdvice.Line> lines = new ArrayList<>();
		long casts = Long.MAX_VALUE;
		for (Map.Entry<String, Integer> e : costs.entrySet())
		{
			String rune = e.getKey();
			int per = e.getValue();
			boolean isFree = free.contains(norm(rune));
			long owned = count(rune, have);
			lines.add(new SpellAdvice.Line(rune, per, isFree, owned));
			if (!isFree && per > 0)
			{
				casts = Math.min(casts, owned / per);
			}
		}
		return new SpellAdvice(title, charges, lines, casts == Long.MAX_VALUE ? -1 : casts, notes);
	}

	/** Owned amount of a rune, including combination runes that count as it. */
	private long count(String rune, Map<String, Long> have)
	{
		long total = have.getOrDefault(norm(rune), 0L);
		for (Map.Entry<String, List<String>> combo : data.comboRunes.entrySet())
		{
			for (String counts : combo.getValue())
			{
				if (norm(counts).equals(norm(rune)))
				{
					total += have.getOrDefault(norm(combo.getKey()), 0L);
					break;
				}
			}
		}
		for (Map.Entry<String, SpellData.Substitute> sub : data.runeSubstitutes.entrySet())
		{
			if (sub.getValue().countsAs != null && norm(sub.getValue().countsAs).equals(norm(rune)))
			{
				total += have.getOrDefault(norm(sub.getKey()), 0L);
			}
		}
		return total;
	}

	private Set<String> freeRunes(Candidate weapon, Candidate shield)
	{
		Set<String> free = new HashSet<>();
		for (SpellData.RuneSource src : data.runeSources)
		{
			if (src.provides == null)
			{
				continue;
			}
			if (weapon.nameContains(src.item) || (shield != null && shield.nameContains(src.item)))
			{
				for (String r : src.provides)
				{
					free.add(norm(r));
				}
			}
		}
		return free;
	}

	private static boolean listContains(List<String> names, Candidate weapon)
	{
		for (String n : names)
		{
			if (weapon.nameContains(n))
			{
				return true;
			}
		}
		return false;
	}

	private static int bookId(String book)
	{
		switch (book)
		{
			case "ancient":
				return BOOK_ANCIENT;
			case "arceuus":
				return BOOK_ARCEUUS;
			default:
				return BOOK_STANDARD;
		}
	}

	private static Map<String, Long> normaliseKeys(Map<String, Long> in)
	{
		Map<String, Long> out = new java.util.HashMap<>();
		in.forEach((k, v) -> out.merge(norm(k), v, Long::sum));
		return out;
	}

	static String norm(String s)
	{
		return s.toLowerCase(Locale.ROOT).replace(" ", "");
	}

	private static String capitalise(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.gearmeup;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Spells, charged weapons and rune sources from {@code spells.json} (OSRS Wiki data).
 * Field names match the JSON keys.
 */
public final class SpellData
{
	List<Spell> spells;
	List<ChargedWeapon> chargedWeapons;
	List<RuneSource> runeSources;
	/** Combination rune -> the elemental runes it counts as. */
	Map<String, List<String>> comboRunes;
	List<String> autocastAncients;
	List<String> autocastArceuus;
	/** e.g. "Sunfire rune" -> counts as "Fire rune". */
	Map<String, Substitute> runeSubstitutes;

	static SpellData load(Gson gson) throws IOException
	{
		try (InputStream in = SpellData.class.getResourceAsStream("spells.json"))
		{
			if (in == null)
			{
				throw new IOException("spells.json is missing from the plugin");
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				SpellData d = gson.fromJson(reader, SpellData.class);
				d.fillNulls();
				return d;
			}
		}
	}

	void fillNulls()
	{
		if (spells == null)
		{
			spells = Collections.emptyList();
		}
		if (chargedWeapons == null)
		{
			chargedWeapons = Collections.emptyList();
		}
		if (runeSources == null)
		{
			runeSources = Collections.emptyList();
		}
		if (comboRunes == null)
		{
			comboRunes = Collections.emptyMap();
		}
		if (autocastAncients == null)
		{
			autocastAncients = Collections.emptyList();
		}
		if (autocastArceuus == null)
		{
			autocastArceuus = Collections.emptyList();
		}
		if (runeSubstitutes == null)
		{
			runeSubstitutes = Collections.emptyMap();
		}
	}

	static final class Spell
	{
		String name;
		String book;
		int level;
		String element;
		int maxHit;
		Map<String, Integer> runes;
		String notes;
	}

	static final class ChargedWeapon
	{
		String name;
		Map<String, Integer> perCharge;
		String notes;
	}

	static final class Substitute
	{
		String countsAs;
		String notes;
	}

	static final class RuneSource
	{
		String item;
		List<String> provides;
		String notes;
	}
}

